// Parse Sheets API response and attach webhook inputs to each recipient row
const webhookData = $('Webhook').first().json.body;

const rows = $json.values || [];
if (rows.length < 2) return [];

const headers = rows[0].map(h => h.trim());
const nameIdx = headers.findIndex(h => h.toLowerCase() === 'name');
const emailIdx = headers.findIndex(h => h.toLowerCase() === 'email');

const dataRows = rows.slice(1);

return dataRows.map(row => ({
  json: {
    Name: row[nameIdx >= 0 ? nameIdx : 0] || '',
    Email: row[emailIdx >= 0 ? emailIdx : 1] || '',
    email_subject: webhookData.email_subject,
    body_type: webhookData.body_type,
    email_body: webhookData.email_body || '',
    email_subject_for_ai: webhookData.email_subject_for_ai || '',
    send_limit: parseInt(webhookData.send_limit) || 50,
    gmail_access_token: webhookData.tokens?.gmail || webhookData.access_token || ''
  }
}));

