// Extract AI body from Gemini response
const aiText = $json.candidates?.[0]?.content?.parts?.[0]?.text || 'Hi there,';
const ctx = $('Attach Webhook Inputs').item.json;
return {
  json: {
    ...ctx,
    final_body: aiText.trim()
  }
};

// Use manual body with {{Name}} placeholder replaced
const userBody = $json.email_body || '';
const previousLink = $('Webhook').first().json.body.previous_step_result || '';
let manual = userBody.replace(/\{\{Name\}\}/gi, $json.Name || '').replace(/\{\{Email\}\}/gi, $json.Email || '');
if (manual.includes('[Your YouTube Video Link]') && previousLink) {
    manual = manual.replace('\[Your YouTube Video Link\]', previousLink);
} else if (manual.includes('{{PREVIOUS_RESULT}}') && previousLink) {
    manual = manual.replace('\{\{PREVIOUS_RESULT\}\}', previousLink);
} else if (previousLink) {
    manual = manual + '\n\nResource Link: ' + previousLink;
}
return {
  json: {
    ...$json,
    final_body: manual
  }
};

// Build a raw RFC 2822 email message and base64url encode it for the Gmail API
const to = $json.Email;
const subject = ($json.email_subject || '').replace(/\{\{Name\}\}/gi, $json.Name || '').replace(/\{\{Email\}\}/gi, $json.Email || '');
const body = $json.final_body || '';
const accessToken = $json.gmail_access_token;

// Build raw message
const rawMessage = [
  `To: ${to}`,
  `Subject: ${subject}`,
  `Content-Type: text/plain; charset=UTF-8`,
  ``,
  body
].join('\r\n');

// Base64url encode (Gmail requires base64url, not standard base64)
const encoded = Buffer.from(rawMessage).toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return {
  json: {
    raw: encoded,
    gmail_access_token: accessToken,
    _to: to,
    _callbackUrl: $('Webhook').first().json.body.callbackUrl || ''
  }
};

